<main id="main" class="profile-page"><div class="page-title"><h1>Seu lugar<br>no clube.</h1><p>Olá, <?= e($profile['name']) ?>.<br>Cuide dos seus dados por aqui.</p></div><section class="profile-layout"><div class="member-card"><img class="avatar" src="<?= e(url('profile_photo')) ?>" alt="Sua foto de perfil" width="160" height="160"><h2><?= e($profile['name']) ?></h2><p><?= e($profile['user_type']==='adm'?'Administrador':'Membro do clube') ?></p><a class="text-link" href="<?= e(url('portfolio')) ?>">Explore os mundos <svg class="icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg></a></div><form class="stack-form form-panel" action="<?= e(url('profile_save')) ?>" method="post" enctype="multipart/form-data"><?php csrf_field() ?><h2>Seu perfil</h2><label for="name">Nome<input id="name" name="name" required minlength="2" maxlength="100" autocomplete="name" value="<?= e($profile['name']) ?>"></label><label for="email">E-mail<input id="email" type="email" value="<?= e($profile['email']) ?>" readonly></label><label for="phone">Telefone<input id="phone" name="phone" type="tel" autocomplete="tel" required maxlength="20" value="<?= e($profile['phone']) ?>"></label><label for="photo">Foto de perfil<input id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp" aria-describedby="photo-help"></label><p id="photo-help" class="field-help">JPG, PNG ou WebP. Até 2 MB e 4096 × 4096 pixels.</p><button class="button red">Salvar alterações</button><a href="<?= e(url('password_forgot')) ?>">Redefinir minha senha</a></form></section></main>
